used = {e['answer'] for r in json.load(open('../../content/puzzles.json')) for e in r['clueAnswers']}
import tiling as Tl, lexicon as lx
def nugly(x):
    g = Tl.good_tilings(x)
    return 9 if not g else sum(lx.ugly_boundaries(t, i == 0, i == len(g[0]) - 1) for i, t in enumerate(g[0]))
out, vet, seen = [], [], set()
for fid, th, ws in T:
    w = [x for x in dict.fromkeys(ws.split()) if x not in used and x not in seen and 5 <= len(x) <= 10]
    drop = [x for x in w if nugly(x) > 1]
    w = [x for x in w if nugly(x) <= 1]
    seen |= set(w); vet += w
    out.append({"id": fid, "category": "themed", "theme": th, "allowProperNouns": True, "words": w})
    print(fid, len(w), ' '.join(w), ' | dropped:', ' '.join(drop))
json.dump(out, open('work/manual_sets-011.json', 'w'), indent=1)
p = 'data/vetted_words.txt'; s = open(p).read(); have = set(s.split())
new = [x.lower() for x in dict.fromkeys(vet) if x.lower() not in have]
if new and '--write-vet' in sys.argv:
    open(p, 'a').write('' + '\n'.join(new) + '\n')

